alter table public.project_states add column if not exists name text; alter table public.project_states add column if not exists organization_id uuid references public.organizations(id); alter table public.project_states add column if not exists site_location text; alter table public.project_states add column if not exists project_type text; alter table public.project_states add column if not exists sector text; alter table public.project_states add column if not exists source_context text; alter table public.project_states add column if not exists summary text; alter table public.project_states add column if not exists priority text; alter table public.project_states add column if not exists commercial_stage text; alter table public.project_states add column if not exists commercial_probability smallint check (commercial_probability between 0 and 100); alter table public.project_states add column if not exists next_action text; alter table public.project_states add column if not exists owner_user_id uuid references auth.users(id); alter table public.project_states add column if not exists archived_at timestamptz; alter table public.project_states add column if not exists archived_by uuid references auth.users(id);
update public.project_states ps set name=o.name, organization_id=o.organization_id, site_location=o.site_location, project_type=o.opportunity_type, sector=o.sector, source_context=o.source_context, summary=o.summary, priority=o.priority, commercial_stage=o.commercial_stage, commercial_probability=o.commercial_probability, next_action=o.next_action, owner_user_id=o.owner_user_id, archived_at=o.archived_at, archived_by=o.archived_by, state=o.lifecycle::text, updated_at=greatest(ps.updated_at,o.updated_at) from public.opportunities o where o.project_state_id=ps.id;
alter table public.project_states alter column name set not null; alter table public.project_states alter column owner_user_id set not null;
alter table public.project_states drop constraint if exists project_states_originating_opportunity_id_fkey; alter table public.project_states drop constraint if exists project_states_originating_opportunity_id_key; alter table public.project_states alter column originating_opportunity_id drop not null;
create index if not exists project_states_workspace_state_idx on public.project_states(workspace_id,state); create index if not exists project_states_workspace_archived_idx on public.project_states(workspace_id,archived_at);
comment on table public.project_states is 'Authoritative continuous E2E state for Ridgewood work from Opportunity through final lifecycle completion. Opportunity is a stage, not a peer entity.'; comment on column public.project_states.state is 'Current lifecycle stage of the authoritative Project State; opportunity-stage values are transitional canonical stages, not separate entity identity.'; comment on column public.project_states.originating_opportunity_id is 'Temporary legacy reconciliation pointer only. New architecture must not depend on Opportunity as a separate identity.';
